import{_ as e,o,c as a,a0 as n}from"./chunks/framework.DZqO77tS.js";const l=JSON.parse('{"title":"What is AuraLinc EcoCONNECT?","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/what-is-ecoconnect.md","filePath":"en/docs/what-is-ecoconnect.md"}'),i={name:"en/docs/what-is-ecoconnect.md"};function r(s,t,h,c,d,u){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="what-is-auralinc-ecoconnect" tabindex="-1">What is AuraLinc EcoCONNECT? <a class="header-anchor" href="#what-is-auralinc-ecoconnect" aria-label="Permalink to &quot;What is AuraLinc EcoCONNECT?&quot;">​</a></h1><p>EcoCONNECT is an <strong>open-source IoT device</strong> that works with AuraLinc, an environmental monitoring system.</p><p>You can modify it, attach your own sensors, and add functions beyond environmental monitoring. It is a device you can <strong>hack</strong>.</p><p>We hope it is useful in school and community workshops, environmental monitoring in agriculture, and in clubs and makerspaces where people try IT engineering.</p><h2 id="about-this-site" tabindex="-1">About this site <a class="header-anchor" href="#about-this-site" aria-label="Permalink to &quot;About this site&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Contents</th></tr></thead><tbody><tr><td><a href="/AuraLinc-Community/en/docs/auralinc/tutorials/">Tutorials</a></td><td>Activities you follow step by step</td></tr><tr><td><a href="/AuraLinc-Community/en/docs/">Docs</a></td><td>Technical notes and FAQ</td></tr><tr><td><a href="/AuraLinc-Community/en/steam/">Workshop materials</a></td><td>Templates for workshops</td></tr><tr><td><a href="/AuraLinc-Community/en/community/">Community</a></td><td>Sharing projects and information</td></tr></tbody></table><h2 id="open-the-black-box" tabindex="-1">Open the black box <a class="header-anchor" href="#open-the-black-box" aria-label="Permalink to &quot;Open the black box&quot;">​</a></h2><p>You can see how it works. You can extend it as you like. You can update it together with others.</p><p>From software (OSS) source code to hardware (OSHWA) design files, the “inside” is open.</p><p><strong>You can see how it works:</strong></p><p>There is no black box. You can check with your own eyes how it runs and how it is built.</p><p><strong>You can extend it as you like:</strong></p><p>Add a feature in code, or make a new part on a 3D printer. That choice is yours.</p><p><strong>You can update it with others:</strong></p><p>When you share an improvement or an idea with the community, it can help someone else’s problem. When you get stuck, you can think it through with the community and look for a solution.</p><h2 id="what-you-can-do-in-the-community-you-do-not-have-to-be-a-developer" tabindex="-1">What you can do in the community (you do not have to be a developer) <a class="header-anchor" href="#what-you-can-do-in-the-community-you-do-not-have-to-be-a-developer" aria-label="Permalink to &quot;What you can do in the community (you do not have to be a developer)&quot;">​</a></h2><p>Your idea can move the world a little.</p><p>Just using it is only the start.</p><ul><li><p><strong>Share what you tried, and photos</strong> (the best kind of feedback)</p></li><li><p><strong>Report “I used it this way”</strong> (that can reveal a new possibility)</p></li><li><p><strong>Say “this part was hard to understand”</strong> (that improves the manual and the design)</p></li><li><p><strong>Of course, write code or improve the hardware</strong> (updates are very welcome)</p></li></ul><p>One person’s idea reaches people everywhere, and ideas from everywhere come back to you.</p><p>Writing a line of code is not the only way to take part.</p><p>“This change made it easier.” “I found this way to use it.”</p><p>— One report like that can be a real help to users everywhere.</p><p>Welcome to a community where you take technology into your own hands and connect with the world.</p>',24)])])}const m=e(i,[["render",r]]);export{l as __pageData,m as default};
